window.blogDetail = {"blogId":1603286995,"blogType":0,"pubTime":"2020-10-21 21:29","cate":"个人日记","cateHex":"b8f6c8cbc8d5bcc7","title":"我读《红楼梦》（43）第三十八回 林潇湘魁夺菊花诗，薛蘅芜讽和螃蟹咏——菊花与螃蟹","commentNum":1,"effect1":66048,"effect2":524294,"ar":0,"block":0,"inproc":false,"appeal":0,"abstract":"在初秋的季节里，总是有那么一抹金黄时不时的映入人们的眼帘，而肃杀的秋也因此带上了些许的诗意。“秋菊有佳色，裛露掇其英”。从陶渊明开始，秋菊就被赋予了孤傲高冷的意象，只因其生在万物凋零的深秋，还有那一份炫人夺目的金黄。使其逐渐成为一种象征性的文化符号，成为隐士的代表和飘然物外的精神寄托，似乎冥冥中那些世外高人与山中隐士将之作为一种与世俗的污秽丑恶，剥削压迫对抗的精神力量。无论是“采菊东篱下，悠然见南...","artype":1,"arUins":"","blogid":1603286995,"voteids":0,"pubtime":1603286995,"replynum":1,"category":"个人日记","effect":66048,"exblogtype":0,"sus_flag":false,"friendrelation":[],"lp_type":0,"lp_id":0,"lp_style":0,"lp_flag":0,"orguin":619774944,"orgblogid":1603286995,"mention_uins":[],"attach":[],"comments":[{"id":1603287270,"postTime":1603287270,"effect":0,"replyNum":0,"content":"这一回算是比较难写的，因为诗多，不太好讲明白，所以准备了很长时间，还好完成了。也算是比较满意的交代吧（虽然挖了不少坑，也不知道填不填的完[em]e120[/em] ） ","capacity":12014,"poster":{"id":"619774944","platform":1,"name":"秋天的怀念 ","emoji":[],"uin":"619774944"},"bmp":"08d015a10000c201","ismyreply":1,"replies":[]}],"html":"","custom_title":"我读《红楼梦》（43）第三十八回 林潇湘魁夺菊花诗，薛蘅芜讽和螃蟹咏——菊花与螃蟹","custom_html":"","uniKey":"http://user.qzone.qq.com/619774944/blog/1603286995"}